
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_lak_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_lak", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.884869308314619e+00, -4.785997923130881e+00, -4.647415949952785e+00, -4.455362035205710e+00, -4.193485866074544e+00, -3.844566104452885e+00, -3.394653562343902e+00, -2.840571795404314e+00, -2.199742538824106e+00, -1.499264469801214e+00, -7.697707274762011e-01, -5.759715176622993e-01, -6.332115119339239e-01, -5.328201784135933e-01, -3.618953381816190e-01, -1.937621813617322e-01, -6.936032545696702e-02, -2.371873519792009e-02, -3.696876500300902e-03, -1.777678036399499e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


